/// <summary>
/// MPJ_17989 - kscerri - 12/14/2021
/// Tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METCustAuditReportTmp))]
public METCustAuditReportTmp getCustAuditReportTmp()
{
    select custAuditReportTmp;
    return custAuditReportTmp;
}

    /// <summary>
    /// MPJ_17989 - kscerri - 12/14/2021
    /// Process report data.
    /// </summary>
    public void processReport()
    {
        Query query;

        contract = this.parmDataContract() as METCustAuditReportContract;

        query = this.processQuery();
        
        this.processdata(query);
    }

    /// <summary>
    /// MPJ_3863 - kscerri - 06/08/2021
    /// </summary>
    /// <returns>query</returns>
    public Query processQuery()
    {
        Query                   query;
        QueryBuildDataSource    qbdsCustTable, 
                                qbdsSysDataBaseLog, 
                                qbdsDirParty,
                                qbdsMETCustTable,
                                qbdsMETCustTableToCust;
        List                    custGroupList   = new List(Types::String);
        List                    custAccountList = new List(Types::String);
        List                    legalEntityList = new List(Types::String);
        ListEnumerator          custGroupListEnum, custAccountListEnum, legalEntityListEnum;

        query = new Query();

        qbdsSysDataBaseLog  = query.addDataSource(tableNum(SysDataBaseLog));

        qbdsCustTable       = qbdsSysDataBaseLog.addDataSource(tableNum(CustTable));
        qbdsCustTable.relations(false);
        qbdsCustTable.addLink(fieldNum(SysDataBaseLog, LogRecId), fieldNum(CustTable, RecId));
        qbdsCustTable.addSelectionField(fieldNum(CustTable, AccountNum));
        qbdsCustTable.fields().dynamic(0);

        qbdsDirParty        = qbdsCustTable.addDataSource(tableNum(DirPartyTable));
        qbdsDirParty.relations(false);
        qbdsDirParty.addLink(fieldNum(CustTable, Party), fieldNum(DirPartyTable, RecId));
        qbdsDirParty.addSelectionField(fieldNum(DirPartyTable, Name));
        qbdsDirParty.fields().dynamic(0);

        qbdsMETCustTable = qbdsSysDataBaseLog.addDataSource(tableNum(METCustTable));
        qbdsMETCustTable.relations(false);
        qbdsMETCustTable.addLink(fieldNum(SysDataBaseLog, LogRecId), fieldNum(METCustTable, RecId));
        qbdsMETCustTable.addSelectionField(fieldNum(METCustTable, AccountNum));
        qbdsMETCustTable.fields().dynamic(0);

        qbdsMETCustTableToCust = qbdsMETCustTable.addDataSource(tableNum(CustTable));
        qbdsMETCustTableToCust.relations(false);
        qbdsMETCustTableToCust.addLink(fieldNum(METCustTable, AccountNum), fieldNum(CustTable, AccountNum));
        qbdsMETCustTableToCust.addSelectionField(fieldNum(CustTable, AccountNum));
        qbdsMETCustTableToCust.fields().dynamic(0);

        // Add required ranges
        // CustomerTableID range in SysDatabaseLog
        qbdsSysDataBaseLog.addRange(fieldNum(SysDataBaseLog, Table)).value(int2Str(tableNum(CustTable)));
        qbdsSysDataBaseLog.addRange(fieldNum(SysDataBaseLog, Table)).value(int2Str(tableNum(METCustTable)));
        // Date range
        qbdsSysDataBaseLog.addRange(fieldNum(SysDataBaseLog, CreatedDateTime)).value(queryRange(contract.parmFromDateChange(), contract.parmToDateChange()));
        //Legal entity range
        legalEntityList     = contract.parmLegalEntity();
        legalEntityListEnum = legalEntityList.getEnumerator();
        while (legalEntityListEnum.moveNext())
        {
            query.allowCrossCompany(true);
            query.addCompanyRange(legalEntityListEnum.current());
        }

        // Cust account range
        if (!contract.parmCustAccount().empty())
        {
            custAccountList     = contract.parmCustAccount();
            custAccountListEnum = custAccountList.getEnumerator();
            while (custAccountListEnum.moveNext())
            {
                qbdsCustTable.addRange(fieldNum(Custtable, accountNum)).value(CustAccountListEnum.current());
                qbdsMETCustTable.addRange(fieldNum(METCustTable, accountNum)).value(CustAccountListEnum.current());
            }
        }

        // Customer group range
        custGroupList     = contract.parmCustGroup();
        custGrouplistEnum = custGroupList.getEnumerator();
        while (custGrouplistEnum.moveNext())
        {
            qbdsCustTable.addRange(fieldNum(CustTable, custGroup)).value(custGrouplistEnum.current());
            qbdsMETCustTableToCust.addRange(fieldNum(CustTable, custGroup)).value(custGrouplistEnum.current());
        }

        return query;
    }

    /// <summary>
    /// MPJ_3863 - kscerri - 06/08/2021
    /// processes data
    /// </summary>
    /// <param name = "_query">query</param>
    public void processData(Query _query)
    {
        QueryRun            queryRun;
        CustTable           custTable;
        SysDataBaseLog      sysDataBaseLog;
        DirPartyTable       dirPartyTable;
        List                list = new List(Types::Container);
        ListEnumerator      listEnumerator;
        container           change;
        System.String       fieldString;
        System.Object       newValue;
        System.Object       oldValue;

        METCustTable        metCustTable;
       
        if (_query)
        {
            queryRun = new QueryRun(_query);
            
            if(!queryRun.next())
            {
                throw warning ("@MET:VendAuditReportWarning");
            }

            do
            {
                custTable       = queryRun.get(tableNum(CustTable));
                sysDataBaseLog  = queryRun.get(tableNum(SysDataBaseLog));
                dirPartyTable   = queryRun.get(tableNum(DirPartyTable));
                metCustTable    = queryRun.get(tableNum(METCustTable));
                
                list            = sysDataBaseLog.getDataAslist();
                listEnumerator  =  list.getEnumerator();
                while (listEnumerator.moveNext())
                {
                    change = listEnumerator.current();
                    [fieldString, newValue, oldValue] = change;

                    if (fieldId2Name(sysDataBaseLog.table, str2int(fieldString)) != fieldStr(CustTable, ModifiedDateTime) &&
                        fieldId2Name(sysDataBaseLog.table, str2int(fieldString)) != fieldStr(CustTable, ModifiedBy))
                    {
                        ttsbegin;

                        if (custTable)
                        {
                            custAuditReportTmp.AccountNum           = custTable.AccountNum;
                            custAuditReportTmp.CustName             = dirPartyTable.Name;
                        }
                        else
                        {
                            custAuditReportTmp.AccountNum           = metCustTable.AccountNum;
                            custAuditReportTmp.CustName             = dirPartyTable::findRec(custTable::find(metCustTable.AccountNum).party).Name;
                        }

                        custAuditReportTmp.DateOfChange         = sysDataBaseLog.CreatedDateTime;
                        
                        custAuditReportTmp.LegalEntity          = sysDataBaseLog.DataAreaId;
                        custAuditReportTmp.NewChange            = METNewChange::Change;
                        custAuditReportTmp.TableName            = tableId2Name(sysDataBaseLog.table);
                        custAuditReportTmp.UserIdCreatedBy      = sysDataBaseLog.CreatedBy;
                        custAuditReportTmp.Field                = fieldId2Name(sysDataBaseLog.table, str2int(fieldString));
                        custAuditReportTmp.NewValue             = newValue;
                        custAuditReportTmp.OldValue             = oldValue;
                        custAuditReportTmp.insert();
                        ttscommit;
                    }
                }                                
            } while (queryRun.next());

        }
    }
